sp_widget.client_script:
api.controller = function($scope,$window) {

    var c = this;


    /*
     * =========================================
     * FORM
     * =========================================
     */

    c.form = {

        student: "",

        opportunity: "",

        round: "",

        mode: "",

        date: "",

        interviewer: "",

        meeting_link: "",

        interview_sys_id: ""

    };


    c.existingInterview = false;

    c.saving = false;

    c.error = "";

    c.success = "";


    /*
     * =========================================
     * LOAD EXISTING INTERVIEW
     * =========================================
     *
     * data.interview comes from
     * the Server Script.
     */

    if (
        c.data.interview &&
        c.data.interview.sys_id
    ) {

        var interview =
            c.data.interview;


        c.existingInterview = true;


        /*
         * Existing interview ID
         */

        c.form.interview_sys_id =
            interview.sys_id;


        /*
         * Candidate
         */

        c.form.student =
            interview.student || "";


        /*
         * Opportunity
         */

        c.form.opportunity =
            interview.opportunity || "";


        /*
         * Interview Round
         */

        c.form.round =
            interview.round || "";


        /*
         * Interview Mode
         */

        c.form.mode =
            interview.mode || "";


        /*
         * Interviewer
         */

        c.form.interviewer =
            interview.interviewer || "";


        /*
         * Meeting Link
         */

        c.form.meeting_link =
            interview.meeting_link || "";


        /*
         * Date
         */

        if (interview.date) {

            /*
             * datetime-local requires a Date object
             */

            var dateString =
                interview.date;


            /*
             * Example:
             *
             * 2026-09-25T19:45
             */

            var parts =
                dateString.split(
                    /[-T: ]/
                );


            if (parts.length >= 5) {

                c.form.date =
                    new Date(
                        parseInt(parts[0], 10),
                        parseInt(parts[1], 10) - 1,
                        parseInt(parts[2], 10),
                        parseInt(parts[3], 10),
                        parseInt(parts[4], 10)
                    );

            }

        }

    }


    /*
     * =========================================
     * BACK
     * =========================================
     */

    c.goBack = function() {

        $window.location.href =
            "?id=campus360_recruiter_dashboard_new";

    };


    /*
     * =========================================
     * SCHEDULE
     * =========================================
     */

    c.schedule = function() {

        c.error = "";

        c.success = "";


        /*
         * Validate
         */

        if (
            !c.form.student ||
            !c.form.opportunity ||
            !c.form.round ||
            !c.form.mode ||
            !c.form.date ||
            !c.form.interviewer
        ) {

            c.error =
                "Please fill all required fields.";

            return;

        }


        c.saving = true;


        /*
         * =========================================
         * SEND DATA TO SERVER
         * =========================================
         */

        c.data.action =
            "schedule";


        c.data.form = {

            student:
                c.form.student,

            opportunity:
                c.form.opportunity,

            round:
                c.form.round,

            mode:
                c.form.mode,

            date:
                formatDateForServiceNow(
                    c.form.date
                ),

            interviewer:
                c.form.interviewer,

            meeting_link:
                c.form.meeting_link,

            /*
             * VERY IMPORTANT
             *
             * If this exists,
             * server will UPDATE
             * instead of INSERT.
             */

            interview_sys_id:
                c.form.interview_sys_id

        };


        /*
         * =========================================
         * SAVE
         * =========================================
         */

        c.server.update().then(

            function(response) {

                c.saving = false;


                if (
                    response.data &&
                    response.data.success
                ) {

                    c.success =
                        c.existingInterview
                        ? "Interview scheduled successfully."
                        : "Interview created successfully.";


                    /*
                     * Go back after save
                     */

                    setTimeout(
                        function() {

                            $window.location.href =
                                "?id=campus360_recruiter_interviews";

                        },
                        800
                    );


                } else {

                    c.error =
                        (
                            response.data &&
                            response.data.error
                        )
                        ||
                        "Unable to schedule interview.";

                }

            },


            function() {

                c.saving = false;

                c.error =
                    "Server error. Please try again.";

            }

        );

    };


    /*
     * =========================================
     * DATE FORMATTER
     * =========================================
     *
     * Converts JavaScript Date to:
     *
     * YYYY-MM-DD HH:mm:ss
     *
     */

    function formatDateForServiceNow(date) {

        if (!date) {
            return "";
        }


        /*
         * If Angular provides a Date object
         */

        if (
            Object.prototype.toString
                .call(date) ===
            "[object Date]"
        ) {

            var year =
                date.getFullYear();


            var month =
                ("0" +
                    (date.getMonth() + 1))
                .slice(-2);


            var day =
                ("0" +
                    date.getDate())
                .slice(-2);


            var hours =
                ("0" +
                    date.getHours())
                .slice(-2);


            var minutes =
                ("0" +
                    date.getMinutes())
                .slice(-2);


            var seconds =
                ("0" +
                    date.getSeconds())
                .slice(-2);


            return (
                year +
                "-" +
                month +
                "-" +
                day +
                " " +
                hours +
                ":" +
                minutes +
                ":" +
                seconds
            );

        }


        /*
         * If it is already a string
         */

        return date;

    }

};

sp_widget.css:
.schedule-page {
  max-width: 1100px;
  margin: 30px auto;
  padding: 0 20px 50px;
  color: #102a56;
}


/* ============================= */
/* HEADER */
/* ============================= */

.page-header {
  background: #ffffff;
  border-radius: 18px;
  padding: 30px 34px;
  margin-bottom: 24px;

  display: flex;
  align-items: center;
  justify-content: space-between;

  box-shadow: 0 8px 25px rgba(30, 55, 90, 0.08);

  border: 1px solid #e1e7f2;
}


.eyebrow {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 2px;
  color: #4d63e8;
}


.page-header h1 {
  margin: 8px 0 6px;

  font-size: 30px;
  font-weight: 700;
}


.page-header p {
  margin: 0;

  color: #70809d;
  font-size: 14px;
}


/* ============================= */
/* FORM CARD */
/* ============================= */

.form-card {
  background: #ffffff;

  border: 1px solid #e1e7f2;

  border-radius: 18px;

  padding: 30px;

  box-shadow: 0 8px 25px rgba(30, 55, 90, 0.06);
}


/* ============================= */
/* FORM TITLE */
/* ============================= */

.form-title {
  border-bottom: 1px solid #e8edf5;

  padding-bottom: 20px;

  margin-bottom: 25px;
}


.form-title h2 {
  margin: 0 0 5px;

  font-size: 20px;
}


.form-title p {
  margin: 0;

  color: #7888a3;

  font-size: 13px;
}


/* ============================= */
/* FORM GRID */
/* ============================= */

.form-grid {
  display: grid;

  grid-template-columns: 1fr 1fr;

  gap: 20px;
}


.form-group {
  display: flex;

  flex-direction: column;
}


.form-group.full-width {
  grid-column: 1 / -1;
}


/* ============================= */
/* LABEL */
/* ============================= */

.form-group label {
  font-size: 13px;

  font-weight: 600;

  color: #30466d;

  margin-bottom: 8px;
}


.form-group label span {
  color: #e05252;
}


/* ============================= */
/* INPUTS */
/* ============================= */

.form-group input,
.form-group select {

  height: 44px;

  border: 1px solid #d6deeb;

  border-radius: 8px;

  padding: 0 13px;

  font-size: 13px;

  color: #24395f;

  background: #fff;

  outline: none;

  transition: 0.2s;
}


.form-group input:focus,
.form-group select:focus {

  border-color: #5368e8;

  box-shadow:
    0 0 0 3px rgba(83, 104, 232, 0.10);
}


/* Disabled pre-filled fields */

.form-group select:disabled {

  background: #f5f7fb;

  color: #64748b;

  cursor: not-allowed;
}


/* ============================= */
/* ACTIONS */
/* ============================= */

.form-actions {

  margin-top: 30px;

  padding-top: 22px;

  border-top: 1px solid #e8edf5;

  display: flex;

  justify-content: flex-end;

  gap: 12px;
}


/* ============================= */
/* BUTTONS */
/* ============================= */

.btn {

  min-width: 130px;

  height: 42px;

  padding: 0 18px;

  border-radius: 8px;

  font-size: 13px;

  font-weight: 600;

  cursor: pointer;

  transition: 0.2s;
}


.btn-primary {

  background: #5368e8;

  color: #fff;

  border: 1px solid #5368e8;
}


.btn-primary:hover {

  background: #4056d5;
}


.btn-secondary {

  background: #fff;

  color: #5368e8;

  border: 1px solid #ccd5e5;
}


.btn-secondary:hover {

  background: #f5f7ff;
}


/* ============================= */
/* ERROR */
/* ============================= */

.error-message {

  margin-top: 20px;

  padding: 12px 15px;

  border-radius: 8px;

  background: #fff1f1;

  border: 1px solid #ffd1d1;

  color: #c63f3f;

  font-size: 13px;
}


/* ============================= */
/* SUCCESS */
/* ============================= */

.success-message {

  margin-top: 20px;

  padding: 12px 15px;

  border-radius: 8px;

  background: #effaf3;

  border: 1px solid #c9ecd5;

  color: #25804a;

  font-size: 13px;
}


/* ============================= */
/* MOBILE */
/* ============================= */

@media (max-width: 768px) {

  .page-header {

    flex-direction: column;

    align-items: flex-start;

    gap: 20px;
  }


  .form-grid {

    grid-template-columns: 1fr;
  }


  .form-group.full-width {

    grid-column: auto;
  }


  .form-actions {

    flex-direction: column;
  }


  .btn {

    width: 100%;
  }

}

sp_widget.script:
(function() {

    /*
     * =========================================
     * INITIAL DATA
     * =========================================
     */

    data.students = [];
    data.opportunities = [];

    data.interview = null;

    data.success = false;
    data.error = "";


    /*
     * =========================================
     * GET EXISTING INTERVIEW ID
     * =========================================
     *
     * URL example:
     *
     * ?id=campus360_recruiter_schedule
     * &interview_sys_id=xxxxxxxx
     *
     */

    var interviewSysId =
        $sp.getParameter("interview_sys_id");


    /*
     * =========================================
     * LOAD STUDENTS
     * =========================================
     */

    var studentGR = new GlideRecord(
        "x_snc_campus360_student_master"
    );

    studentGR.orderBy("student_name");

    studentGR.query();

    while (studentGR.next()) {

        data.students.push({

            sys_id:
                studentGR.getUniqueValue(),

            name:
                studentGR.getValue("student_name")

        });

    }


    /*
     * =========================================
     * LOAD OPPORTUNITIES
     * =========================================
     */

    var opportunityGR = new GlideRecord(
        "x_snc_campus360_placement_opportunity"
    );

    opportunityGR.orderBy("opportunity_title");

    opportunityGR.query();

    while (opportunityGR.next()) {

        data.opportunities.push({

            sys_id:
                opportunityGR.getUniqueValue(),

            label:
                opportunityGR.getValue("opportunity_id") +
                " - " +
                opportunityGR.getValue("opportunity_title")

        });

    }


    /*
     * =========================================
     * LOAD EXISTING INTERVIEW
     * =========================================
     *
     * If interview_sys_id exists,
     * DO NOT create a new record.
     *
     * Load the existing record instead.
     */

    if (interviewSysId) {

        var existingInterview =
            new GlideRecord(
                "x_snc_campus360_recruiter_interview"
            );


        if (existingInterview.get(interviewSysId)) {

            data.interview = {

                sys_id:
                    existingInterview.getUniqueValue(),

                student:
                    existingInterview.getValue("student"),

                student_display:
                    existingInterview.getDisplayValue("student"),

                opportunity:
                    existingInterview.getValue("opportunity"),

                opportunity_display:
                    existingInterview.getDisplayValue("opportunity"),

                round:
                    existingInterview.getValue(
                        "interview_round"
                    ),

                round_display:
                    existingInterview.getDisplayValue(
                        "interview_round"
                    ),

                mode:
                    existingInterview.getValue(
                        "interview_mode"
                    ),

                mode_display:
                    existingInterview.getDisplayValue(
                        "interview_mode"
                    ),

                interviewer:
                    existingInterview.getValue(
                        "interviewer"
                    ),

                meeting_link:
                    existingInterview.getValue(
                        "meeting_link"
                    ),

                /*
                 * Display value is used because
                 * datetime-local needs:
                 *
                 * YYYY-MM-DDTHH:mm
                 */

                date:
                    existingInterview
                        .getDisplayValue("interview_date")
                        .replace(" ", "T")
                        .substring(0, 16)

            };

        } else {

            data.error =
                "Interview record was not found.";

        }

    }


    /*
     * =========================================
     * SCHEDULE / UPDATE INTERVIEW
     * =========================================
     */

    if (input && input.action == "schedule") {

        var form = input.form;

        /*
         * Validate
         */

        if (!form ||
            !form.student ||
            !form.opportunity ||
            !form.round ||
            !form.mode ||
            !form.date ||
            !form.interviewer) {

            data.success = false;

            data.error =
                "Please fill all required fields.";

            return;
        }


        /*
         * =========================================
         * DETERMINE INSERT OR UPDATE
         * =========================================
         */

        var interview =
            new GlideRecord(
                "x_snc_campus360_recruiter_interview"
            );


        /*
         * Existing interview
         *
         * UPDATE
         */

        if (form.interview_sys_id) {

            if (!interview.get(form.interview_sys_id)) {

                data.success = false;

                data.error =
                    "Existing interview could not be found.";

                return;
            }

        }

        /*
         * New interview
         *
         * INSERT
         */

        else {

            interview.initialize();

        }


        /*
         * =========================================
         * SET CANDIDATE
         * =========================================
         */

        interview.setValue(
            "student",
            form.student
        );


        /*
         * =========================================
         * SET OPPORTUNITY
         * =========================================
         */

        interview.setValue(
            "opportunity",
            form.opportunity
        );


        /*
         * =========================================
         * SET ROUND
         * =========================================
         */

        interview.setValue(
            "interview_round",
            form.round
        );


        /*
         * =========================================
         * SET MODE
         * =========================================
         */

        interview.setValue(
            "interview_mode",
            form.mode
        );


        /*
         * =========================================
         * SET DATE
         * =========================================
         */

        interview.setValue(
            "interview_date",
            form.date
        );


        /*
         * =========================================
         * SET INTERVIEWER
         * =========================================
         */

        interview.setValue(
            "interviewer",
            form.interviewer
        );


        /*
         * =========================================
         * SET MEETING LINK
         * =========================================
         */

        interview.setValue(
            "meeting_link",
            form.meeting_link || ""
        );


        /*
         * =========================================
         * STATUS
         * =========================================
         */

        interview.setValue(
            "status",
            "Scheduled"
        );


        /*
         * =========================================
         * RESULT
         * =========================================
         */

        interview.setValue(
            "result",
            "Pending"
        );


        /*
         * =========================================
         * INTERVIEW ID
         * =========================================
         *
         * Generate only for NEW records.
         */

        if (!form.interview_sys_id) {

            interview.setValue(
                "interview_id",
                "INT" +
                new GlideDateTime()
                    .getNumericValue()
            );

        }


        /*
         * =========================================
         * SAVE
         * =========================================
         */

        var savedSysId;


        if (form.interview_sys_id) {

            /*
             * UPDATE EXISTING RECORD
             */

            savedSysId =
                interview.update();

        } else {

            /*
             * INSERT NEW RECORD
             */

            savedSysId =
                interview.insert();

        }


        /*
         * =========================================
         * RESPONSE
         * =========================================
         */

        if (savedSysId) {

            data.success = true;

            data.interview_sys_id =
                savedSysId;

        } else {

            data.success = false;

            data.error =
                "Interview could not be saved.";

        }

    }

})();
